-- ============================================
-- LUMA — Thème 14 : MOYEN 3/3 x4 — Réserver un motel en dernière minute
-- ============================================


update scenarios set content = '{"characters": {"clerk": "l''employé du motel"}, "start_node": "n1", "nodes": {"n1": {"speaker": "you_thought", "text": "(It''s 10pm, you''re exhausted from driving, and need to find a place to stay fast.)", "text_fr": "(Il est 22h, vous êtes épuisé de conduire, et devez trouver un endroit où dormir vite.)", "choices": [{"text": "(Call the first motel you see advertised on a roadside sign.)", "text_fr": "(Appelle le premier motel vu annoncé sur un panneau au bord de la route.)", "next": "n2"}, {"text": "(Pull into the motel parking lot directly to ask in person.)", "text_fr": "(Te gares directement dans le parking du motel pour demander en personne.)", "next": "n2b"}]}, "n2": {"speaker": "clerk", "text": "Sunset Motel, how can I help you?", "text_fr": "Sunset Motel, comment puis-je vous aider ?", "choices": [{"text": "Hi, do you have any rooms available for tonight?", "text_fr": "Bonjour, vous avez des chambres disponibles pour ce soir ?", "next": "n3"}]}, "n2b": {"speaker": "clerk", "text": "Evening! Looking for a room for tonight?", "text_fr": "Bonsoir ! Vous cherchez une chambre pour ce soir ?", "choices": [{"text": "Yes, please, I''ve been driving all day and I''m exhausted.", "text_fr": "Oui, s''il vous plaît, j''ai conduit toute la journée et je suis épuisé.", "next": "n3"}]}, "n3": {"speaker": "clerk", "text": "You''re in luck, we''ve got one room left, a queen bed for $75.", "text_fr": "Vous avez de la chance, il nous reste une chambre, un lit queen à 75$.", "choices": [{"text": "That works perfectly, I''ll take it.", "text_fr": "Ça marche parfaitement, je la prends.", "next": "n4"}, {"text": "Does that include breakfast, or is that separate?", "text_fr": "Ça inclut le petit-déjeuner, ou c''est séparé ?", "next": "n4"}]}, "n4": {"speaker": "clerk", "text": "Just need your ID and a card for incidentals, and you''re all set.", "text_fr": "J''ai juste besoin de votre pièce d''identité et d''une carte pour les frais accessoires, et c''est bon.", "choices": [{"text": "Here you go. (Hands over ID and card.)", "text_fr": "Voici. (Tend la pièce d''identité et la carte.)", "next": "n5"}]}, "n5": {"speaker": "clerk", "text": "Perfect, you''re in room 12, just around the corner. Ice machine''s right outside.", "text_fr": "Parfait, vous êtes en chambre 12, juste au coin. La machine à glaçons est juste dehors.", "choices": [{"text": "Thank you so much, I really needed this after today''s drive.", "text_fr": "Merci beaucoup, j''en avais vraiment besoin après la conduite d''aujourd''hui.", "next": "n6"}]}, "n6": {"speaker": "clerk", "text": "I bet! Checkout is at 11am, but let us know if you need to sleep in.", "text_fr": "Je m''en doute ! Le départ est à 11h, mais dites-nous si vous avez besoin de faire la grasse matinée.", "choices": [{"text": "Good to know, thank you for everything.", "text_fr": "Bon à savoir, merci pour tout.", "next": "end_booked"}]}, "end_booked": {"speaker": "clerk", "text": "Sleep well, and safe travels tomorrow!", "text_fr": "Dormez bien, et bonne route demain !", "end": true, "ending_label": "Motel trouvé et réservé en dernière minute 🏨🛏️"}}}'::jsonb, is_playable = true
where title = 'Réserver un motel en dernière minute'
  and theme_id = (select id from scenario_themes where position = 14 and language_id = (select id from languages where code = 'en'));
